"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { QuoteMark } from "./icons";

// Quote: generated by UIX from the design system. Same variants and sizes as the Figma component.

const quoteVariants = cva(
  "flex w-full flex-col text-fg-primary",
  {
    variants: {
      appearance: {
        default: "gap-4",
        accent: "border-l-4 border-line-brand pl-5 py-1 gap-4",
        large: "items-center text-center gap-6 [&>blockquote]:text-heading-4 [&>figcaption]:flex-col",
      },
    },
    defaultVariants: {
      appearance: "default",
    },
  },
);

export interface QuoteProps
  extends Omit<React.HTMLAttributes<HTMLElement>, "role">,
    VariantProps<typeof quoteVariants> {
  author?: React.ReactNode;
  role?: React.ReactNode;
  /** Avatar beside the author (for example <Avatar initials="RS" />). */
  avatar?: React.ReactNode;
}

const Quote = React.forwardRef<HTMLElement, QuoteProps>(
  ({ className, appearance, author, role, avatar, children, ...props }, ref) => (
    <figure data-slot="quote" data-kind="surface" ref={ref} className={cn(quoteVariants({ appearance }), className)} {...props}>
      {appearance === "large" ? <QuoteMark aria-hidden className="size-8 text-icon-brand" /> : null}
      <blockquote className="text-body-large text-fg-primary">{children}</blockquote>
      {author ? (
        <figcaption className="flex items-center gap-3">
          {avatar}
          <span className="flex flex-col gap-0-5">
            <span className="text-label-large text-fg-primary">{author}</span>
            {role ? <span className="text-body-small text-fg-secondary">{role}</span> : null}
          </span>
        </figcaption>
      ) : null}
    </figure>
  ),
);
Quote.displayName = "Quote";

export { Quote, quoteVariants };
